// โลกอื่นที่ผู้เล่นเห็นผ่านรอยแยก/จดหมายเทพธิดา — สุ่มครั้งเดียวต่อชีวิตให้ข้อความตรงกัน
function riftWorld(s) {
  if (!s.riftWorld || s.riftWorld === s.W.id) s.riftWorld = pick(WORLDS.filter(w => w.id !== s.W.id)).id;
  return WORLDS.find(w => w.id === s.riftWorld);
}

